def prompt(i):
    p,l,d,n = SHOTS[i-1]
    note = f" Handwritten marker note + arrow: '{n}'." if n else " No text."
    if "'you'" in d: note += " 'you' = simple white round-headed stick figure with dot eyes."
    else: note += " No stick figures; all people drawn realistically."
    return STYLE + d + "." + note
